#include <iostream>
int main() {
    int a, b;
    if (!(std::cin >> a >> b) || a < 0 || a > 100000 || b < 0 || b > 100000 || (a == 0 && b == 0)) {
        std::cout << "invalid\n"; return 0;
    }
    while (b != 0) {
        int remainder = a % b;
        a = b;
        b = remainder;
    }
    std::cout << a << '\n';
}

laboratory.referenceCode:
#include <iostream>
int main() {
    int a, b;
    if (!(std::cin >> a >> b)) { std::cout << "invalid\n"; return 0; }
    if (a < 0 || a > 100000 || b < 0 || b > 100000 || (a == 0 && b == 0)) {
        std::cout << "invalid\n"; return 0;
    }
    int steps = 0;
    while (b != 0) {
        int r = a % b;
        a = b;
        b = r;
        ++steps;
    }
    std::cout << a << ' ' << steps << '\n';
}

